WITH sales_ship AS ( SELECT cs.cs_ship_mode_sk, cs.cs_warehouse_sk, hd.hd_income_band_sk, i.i_category, SUM(cs.cs_net_paid) AS total_net_paid, AVG(cs.cs_net_paid) AS avg_net_paid, COUNT(*) AS sales_count FROM catalog_sales cs JOIN household_demographics hd ON cs.cs_ship_hdemo_sk = hd.hd_demo_sk JOIN item i ON cs.cs_item_sk = i.i_item_sk GROUP BY cs.cs_ship_mode_sk, cs.cs_warehouse_sk, hd.hd_income_band_sk, i.i_category ), returns_ship AS ( SELECT cr.cr_ship_mode_sk, cr.cr_warehouse_sk, hd.hd_income_band_sk, i.i_category, SUM(cr.cr_refunded_cash) AS total_refunded_cash, AVG(cr.cr_refunded_cash) AS avg_refunded_cash, COUNT(*) AS returns_count FROM catalog_returns cr JOIN household_demographics hd ON cr.cr_refunded_hdemo_sk = hd.hd_demo_sk JOIN item i ON cr.cr_item_sk = i.i_item_sk GROUP BY cr.cr_ship_mode_sk, cr.cr_warehouse_sk, hd.hd_income_band_sk, i.i_category ) SELECT s.cs_ship_mode_sk, s.cs_warehouse_sk, s.hd_income_band_sk, s.i_category, s.total_net_paid, r.total_refunded_cash, CASE WHEN s.total_net_paid = 0 THEN 0 ELSE r.total_refunded_cash / NULLIF(s.total_net_paid, 0) END AS refund_to_sales_ratio, RANK() OVER (PARTITION BY s.cs_ship_mode_sk ORDER BY r.total_refunded_cash DESC) AS refund_rank_in_ship_mode, SUM(s.total_net_paid) OVER (PARTITION BY s.cs_ship_mode_sk ORDER BY s.cs_warehouse_sk ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_net_paid_by_ship_mode, CASE WHEN r.total_refunded_cash > s.total_net_paid * 0.5 THEN 'ALERT' ELSE 'NORMAL' END AS alert_flag FROM sales_ship s LEFT JOIN returns_ship r ON s.cs_ship_mode_sk = r.cr_ship_mode_sk AND s.cs_warehouse_sk = r.cr_warehouse_sk AND s.hd_income_band_sk = r.hd_income_band_sk AND s.i_category = r.i_category ORDER BY s.cs_ship_mode_sk, refund_rank_in_ship_mode LIMIT 100
